// Parsed-model cache (Round 36.22, Eddie 2026-11-25 — the
// battle-entry freeze fix; diagnosis: r3621-verify/REPORT.md).
//
// THE DEFECT this kills: until now there was NO parsed-model
// cache anywhere. Every mount of a modeled fighter — the
// Navidex Stage canvas (keyed per fighter, so every swipe was a
// full teardown), the deck cards' 3D face, the battle arena's
// buildFighter — built a brand-new GLTFLoader and re-parsed the
// GLB from bytes ON THE MAIN THREAD. A parse is seconds of
// synchronous work (Solara ~7.7 s of blocked heartbeat in the
// VM; the Multiverse Bot worst of all, chaining a second parse
// for its Sphere Drone). On a phone that reads as a frozen
// screen: taps, navigation and animation simply do not run
// while it happens.
//
// THE FIX: parse each model URL exactly once per session and
// keep the parsed scene as a pristine MASTER that is never
// added to a live scene. Every mount takes a LEASE: a
// SkeletonUtils clone of the master (geometry / materials /
// textures shared with the master and sibling clones; the
// clone's root carries the instance's own transform, and a
// rigged model's idle clip binds to the clone's bones by name,
// so Bot's idle and Prime Zero's walk-only rig behave exactly
// as they did on a fresh parse). Consumers release the lease
// when they unmount instead of disposing the model's resources
// — the cache owns disposal.
//
// CACHE DISCIPLINE (the old force-dispose cleanup was guarding
// phone memory; the freeze must not be traded for an OOM): at
// most CACHE_CAP masters are retained, LRU-evicted. An evicted
// master is disposed (geometry / materials / textures) as soon
// as its last live clone is released — never out from under a
// standing fighter.
//
// This module imports three.js, so it must only ever be reached
// from the lazy 3D chunks (ModelCanvas, ElementalWorld) or via
// the dynamic import in utils/modelPrefetch — never statically
// from the main bundle.
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone as skeletonClone } from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface ParsedModel {
  scene: THREE.Group;
  animations: THREE.AnimationClip[];
}

export interface ModelLease {
  // A clone of the cached master — yours to transform, add to a
  // scene, and animate. Never dispose its geometry/materials;
  // release() hands the accounting back to the cache.
  scene: THREE.Group;
  animations: THREE.AnimationClip[];
  release: () => void;
}

const CACHE_CAP = 6;

interface CacheEntry {
  promise: Promise<ParsedModel>;
  parsed: ParsedModel | null;
  live: number; // clones currently handed out
  waiters: number; // acquires in flight against a pending parse
  stale: boolean; // evicted from the map: dispose once free
}

const entries = new Map<string, CacheEntry>();
const loader = new GLTFLoader();

function disposeParsed(parsed: ParsedModel): void {
  parsed.scene.traverse(obj => {
    const mesh = obj as THREE.Mesh;
    if (mesh.geometry) mesh.geometry.dispose();
    const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
    const disposeOne = (m: THREE.Material) => {
      const withMap = m as THREE.MeshStandardMaterial;
      if (withMap.map) withMap.map.dispose();
      m.dispose();
    };
    if (Array.isArray(material)) material.forEach(disposeOne);
    else if (material) disposeOne(material);
  });
}

function maybeDispose(entry: CacheEntry): void {
  if (entry.stale && entry.parsed && entry.live === 0 && entry.waiters === 0) {
    const parsed = entry.parsed;
    entry.parsed = null;
    disposeParsed(parsed);
  }
}

function evictIfNeeded(protectedUrl: string): void {
  while (entries.size > CACHE_CAP) {
    let victim: string | null = null;
    for (const key of entries.keys()) {
      if (key !== protectedUrl) {
        victim = key;
        break;
      }
    }
    if (victim === null) return;
    const entry = entries.get(victim);
    entries.delete(victim);
    if (entry) {
      entry.stale = true;
      maybeDispose(entry);
    }
  }
}

function entryFor(url: string): CacheEntry {
  const existing = entries.get(url);
  if (existing) {
    // LRU touch: re-insertion moves the entry to the tail.
    entries.delete(url);
    entries.set(url, existing);
    return existing;
  }
  const entry: CacheEntry = {
    promise: Promise.resolve(null as unknown as ParsedModel),
    parsed: null,
    live: 0,
    waiters: 0,
    stale: false,
  };
  entry.promise = new Promise<ParsedModel>((resolve, reject) => {
    loader.load(
      url,
      gltf => {
        entry.parsed = {
          scene: gltf.scene as THREE.Group,
          animations: gltf.animations || [],
        };
        resolve(entry.parsed);
      },
      undefined,
      err => {
        // A failed parse leaves NO entry behind: the next
        // acquire starts a fresh parse (ModelCanvas's one-retry
        // honesty depends on this).
        if (entries.get(url) === entry) entries.delete(url);
        entry.stale = true;
        reject(err instanceof Error ? err : new Error(`model parse failed: ${url}`));
      }
    );
  });
  // An entry evicted while its parse was still in flight: once
  // the parse lands, if nobody holds or awaits it, the master
  // goes straight back out instead of lingering off the books.
  entry.promise.then(
    () => maybeDispose(entry),
    () => undefined
  );
  entries.set(url, entry);
  evictIfNeeded(url);
  return entry;
}

// Take a lease on a fighter's model: resolves with a CLONE of
// the cached parsed scene (parsing first, once, if this URL has
// never been parsed — or was evicted — this session). Call
// release() exactly when the clone leaves its scene for good.
export async function acquireModel(url: string): Promise<ModelLease> {
  const entry = entryFor(url);
  entry.waiters += 1;
  try {
    const parsed = await entry.promise;
    const scene = skeletonClone(parsed.scene) as THREE.Group;
    entry.live += 1;
    let released = false;
    return {
      scene,
      animations: parsed.animations,
      release: () => {
        if (released) return;
        released = true;
        entry.live -= 1;
        maybeDispose(entry);
      },
    };
  } finally {
    entry.waiters -= 1;
    maybeDispose(entry);
  }
}

// Parse-warming (the Round 36.22 prefetch): start the fetch +
// parse for a URL whose card is standing, so a later acquire is
// a clone instead of a main-thread parse. Never rejects — a
// failed warm costs nothing; the real load path keeps its own
// retry and portrait fallback.
export function warmModel(url: string): Promise<void> {
  if (!url) return Promise.resolve();
  const entry = entryFor(url);
  return entry.promise.then(
    () => undefined,
    () => undefined
  );
}

// Test/inspection hook: the cache's current contents.
export function modelCacheInfo(): { size: number; urls: string[]; parsedUrls: string[] } {
  const parsedUrls: string[] = [];
  for (const [url, entry] of entries) {
    if (entry.parsed) parsedUrls.push(url);
  }
  return { size: entries.size, urls: [...entries.keys()], parsedUrls };
}
